import{_ as l,a0 as p,w as d,s as o,ao as r,I as n,x as s,a1 as a,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const v=JSON.parse('{"title":"过渡到 nftables | LCTT x X-CMD","titleTemplate":false,"description":"过渡到 nftables | LCTT (201910) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"过渡到 nftables | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"过渡到 nftables | LCTT (201910) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201910/20191021 Transition to Nftables","title":"过渡到 nftables","tag":"201910","desc":""},"relativePath":"201910/20191021 Transition to Nftables.md","filePath":"[post].md"}'),c={name:"201910/20191021 Transition to Nftables.md"};function f(h,e,u,g,b,k){const t=p("Link");return d(),o("div",null,[e[15]||(e[15]=r(`<h1 id="过渡到-nftables" tabindex="-1">过渡到 nftables <a class="header-anchor" href="#过渡到-nftables" aria-label="Permalink to “过渡到 nftables”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/201910/29/085827o8b7rbswjjr7ijsr.jpg" alt=""></p><blockquote><p>开源世界中的每个主要发行版都在演进，逐渐将 nftables 作为了默认防火墙。换言之，古老的 iptables 现在已经消亡。本文是有关如何构建 nftables 的教程。</p></blockquote><p>当前，有一个与 nftables 兼容的 iptables-nft 后端，但是很快，即使是它也不再提供了。另外，正如 Red Hat 开发人员所指出的那样，有时它可能会错误地转换规则。我们需要知道如何构建自己的 nftables，而不是依赖于 iptables 到 nftables 的转换器。</p><p>在 nftables 中，所有地址族都遵循一个规则。与 iptables 不同，nftables 在用户空间中运行，iptables 中的每个模块都运行在内核（空间）中。它很少需要更新内核，并带有一些新功能，例如映射、地址族和字典。</p><h3 id="地址族" tabindex="-1">地址族 <a class="header-anchor" href="#地址族" aria-label="Permalink to “地址族”">​</a></h3><p>地址族确定要处理的数据包的类型。在 nftables 中有六个地址族，它们是：</p><ul><li>ip</li><li>ipv6</li><li>inet</li><li>arp</li><li>bridge</li><li>netdev</li></ul><p>在 nftables 中，ipv4 和 ipv6 协议可以被合并为一个称为 inet 的单一地址族。因此，我们不需要指定两个规则：一个用于 ipv4，另一个用于 ipv6。如果未指定地址族，它将默认为 ip 协议，即 ipv4。我们感兴趣的领域是 inet 地址族，因为大多数家庭用户将使用 ipv4 或 ipv6 协议。</p><h3 id="nftables" tabindex="-1">nftables <a class="header-anchor" href="#nftables" aria-label="Permalink to “nftables”">​</a></h3><p>典型的 nftables 规则包含三个部分：表、链和规则。</p><p>表是链和规则的容器。它们由其地址族和名称来标识。链包含 inet/arp/bridge/netdev 等协议所需的规则，并具有三种类型：过滤器、NAT 和路由。nftables 规则可以从脚本加载，也可以在终端键入，然后另存为规则集。</p><p>对于家庭用户，默认链为过滤器。inet 系列包含以下钩子：</p><ul><li>Input</li><li>Output</li><li>Forward</li><li>Pre-routing</li><li>Post-routing</li></ul><h3 id="使用脚本还是不用" tabindex="-1">使用脚本还是不用？ <a class="header-anchor" href="#使用脚本还是不用" aria-label="Permalink to “使用脚本还是不用？”">​</a></h3><p>最大的问题之一是我们是否可以使用防火墙脚本。答案是：这是你自己的选择。这里有一些建议：如果防火墙中有数百条规则，那么最好使用脚本，但是如果你是典型的家庭用户，则可以在终端中键入命令，然后（保存并在重启时）加载规则集。每种选择都有其自身的优缺点。在本文中，我们将在终端中键入它们以构建防火墙。</p><p>nftables 使用一个名为 <code>nft</code> 的程序来添加、创建、列出、删除和加载规则。确保使用以下命令将 nftables 与 conntrackd 和 netfilter-persistent 软件包一起安装，并删除 iptables：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>apt-get install nftables conntrackd netfilter-persistent</span></span>
<span class="line"><span>apt-get purge iptables</span></span></code></pre></div><p><code>nft</code> 需要以 root 身份运行或使用 <code>sudo</code> 运行。使用以下命令分别列出、刷新、删除规则集和加载脚本。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nft list ruleset</span></span>
<span class="line"><span>nft flush ruleset</span></span>
<span class="line"><span>nft delete table inet filter</span></span>
<span class="line"><span>/usr/sbin/nft -f /etc/nftables.conf</span></span></code></pre></div><h3 id="输入策略" tabindex="-1">输入策略 <a class="header-anchor" href="#输入策略" aria-label="Permalink to “输入策略”">​</a></h3><p>就像 iptables 一样，防火墙将包含三部分：输入（<code>input</code>）、转发（<code>forward</code>）和输出（<code>output</code>）。在终端中，为输入（<code>input</code>）策略键入以下命令。在开始之前，请确保已刷新规则集。我们的默认策略将会删除所有内容。我们将在防火墙中使用 inet 地址族。将以下规则以 root 身份添加或使用 <code>sudo</code> 运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nft add table inet filter</span></span>
<span class="line"><span>nft add chain inet filter input { type filter hook input priority 0 \\; counter \\; policy drop \\; }</span></span></code></pre></div><p>你会注意到有一个名为 <code>priority 0</code> 的东西。这意味着赋予该规则更高的优先级。挂钩通常赋予负整数，这意味着更高的优先级。每个挂钩都有自己的优先级，过滤器链的优先级为 0。你可以检查 nftables Wiki 页面以查看每个挂钩的优先级。</p><p>要了解你计算机中的网络接口，请运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ip link show</span></span></code></pre></div><p>它将显示已安装的网络接口，一个是本地主机、另一个是以太网端口或无线端口。以太网端口的名称如下所示：<code>enpXsY</code>，其中 <code>X</code> 和 <code>Y</code> 是数字，无线端口也是如此。我们必须允许本地主机的流量，并且仅允许从互联网建立的传入连接。</p><p>nftables 具有一项称为裁决语句的功能，用于解析规则。裁决语句为 <code>accept</code>、<code>drop</code>、<code>queue</code>、<code>jump</code>、<code>goto</code>、<code>continue</code> 和 <code>return</code>。由于这是一个很简单的防火墙，因此我们将使用 <code>accept</code> 或 <code>drop</code> 处理数据包。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nft add rule inet filter input iifname lo accept</span></span>
<span class="line"><span>nft add rule inet filter input iifname enpXsY ct state new, established, related accept</span></span></code></pre></div><p>接下来，我们必须添加规则以保护我们免受隐秘扫描。并非所有的隐秘扫描都是恶意的，但大多数都是。我们必须保护网络免受此类扫描。第一组规则列出了要测试的 TCP 标志。在这些标志中，第二组列出了要与第一组匹配的标志。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nft add rule inet filter input iifname enpXsY tcp flags \\&amp; \\(syn\\|fin\\) == \\(syn\\|fin\\) drop</span></span>
<span class="line"><span>nft add rule inet filter input iifname enpXsY tcp flags \\&amp; \\(syn\\|rst\\) == \\(syn\\|rst\\) drop</span></span>
<span class="line"><span>nft add rule inet filter input iifname enpXsY tcp flags \\&amp; \\(fin\\|rst\\) == \\(fin\\|rst\\) drop</span></span>
<span class="line"><span>nft add rule inet filter input iifname enpXsY tcp flags \\&amp; \\(ack\\|fin\\) == fin drop</span></span>
<span class="line"><span>nft add rule inet filter input iifname enpXsY tcp flags \\&amp; \\(ack\\|psh\\) == psh drop</span></span>
<span class="line"><span>nft add rule inet filter input iifname enpXsY tcp flags \\&amp; \\(ack\\|urg\\) == urg drop</span></span></code></pre></div><p>记住，我们在终端中键入这些命令。因此，我们必须在一些特殊字符之前添加一个反斜杠，以确保终端能够正确解释该斜杠。如果你使用的是脚本，则不需要这样做。</p><h3 id="关于-icmp-的警告" tabindex="-1">关于 ICMP 的警告 <a class="header-anchor" href="#关于-icmp-的警告" aria-label="Permalink to “关于 ICMP 的警告”">​</a></h3><p>互联网控制消息协议（ICMP）是一种诊断工具，因此不应完全丢弃该流量。完全阻止 ICMP 的任何尝试都是不明智的，因为它还会导致停止向我们提供错误消息。仅启用最重要的控制消息，例如回声请求、回声应答、目的地不可达和超时等消息，并拒绝其余消息。回声请求和回声应答是 <code>ping</code> 的一部分。在输入策略中，我们仅允许回声应答、而在输出策略中，我们仅允许回声请求。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nft add rule inet filter input iifname enpXsY icmp type { echo-reply, destination-unreachable, time-exceeded } limit rate 1/second accept</span></span>
<span class="line"><span>nft add rule inet filter input iifname enpXsY ip protocol icmp drop</span></span></code></pre></div><p>最后，我们记录并丢弃所有无效数据包。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nft add rule inet filter input iifname enpXsY ct state invalid log flags all level info prefix \\”Invalid-Input: \\”</span></span>
<span class="line"><span>nft add rule inet filter input iifname enpXsY ct state invalid drop</span></span></code></pre></div><h3 id="转发和输出策略" tabindex="-1">转发和输出策略 <a class="header-anchor" href="#转发和输出策略" aria-label="Permalink to “转发和输出策略”">​</a></h3><p>在转发和输出策略中，默认情况下我们将丢弃数据包，仅接受已建立连接的数据包。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nft add chain inet filter forward { type filter hook forward priority 0 \\; counter \\; policy drop \\; }</span></span>
<span class="line"><span>nft add rule inet filter forward ct state established, related accept</span></span>
<span class="line"><span>nft add rule inet filter forward ct state invalid drop</span></span>
<span class="line"><span>nft add chain inet filter output { type filter hook output priority 0 \\; counter \\; policy drop \\; }</span></span></code></pre></div><p>典型的桌面用户只需要端口 80 和 443 即可访问互联网。最后，允许可接受的 ICMP 协议并在记录无效数据包时丢弃它们。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nft add rule inet filter output oifname enpXsY tcp dport { 80, 443 } ct state established accept</span></span>
<span class="line"><span>nft add rule inet filter output oifname enpXsY icmp type { echo-request, destination-unreachable, time-exceeded } limit rate 1/second accept</span></span>
<span class="line"><span>nft add rule inet filter output oifname enpXsY ip protocol icmp drop</span></span>
<span class="line"><span>nft add rule inet filter output oifname enpXsY ct state invalid log flags all level info prefix \\”Invalid-Output: \\”</span></span>
<span class="line"><span>nft add rule inet filter output oifname enpXsY ct state invalid drop</span></span></code></pre></div><p>现在我们必须保存我们的规则集，否则重新启动时它将丢失。为此，请运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo nft list ruleset. &gt; /etc/nftables.conf</span></span></code></pre></div><p>我们须在引导时加载 nftables，以下将在 systemd 中启用 nftables 服务：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo systemctl enable nftables</span></span></code></pre></div><p>接下来，编辑 nftables 单元文件以删除 <code>Execstop</code> 选项，以避免在每次引导时刷新规则集。该文件通常位于 <code>/etc/systemd/system/sysinit.target.wants/nftables.service</code>。现在重新启动nftables：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo systemctl restart nftables</span></span></code></pre></div><h3 id="在-rsyslog-中记录日志" tabindex="-1">在 rsyslog 中记录日志 <a class="header-anchor" href="#在-rsyslog-中记录日志" aria-label="Permalink to “在 rsyslog 中记录日志”">​</a></h3><p>当你记录丢弃的数据包时，它们直接进入 syslog，这使得读取该日志文件非常困难。最好将防火墙日志重定向到单独的文件。在 <code>/var/log</code> 目录中创建一个名为 <code>nftables</code> 的目录，并在其中创建两个名为 <code>input.log</code> 和 <code>output.log</code> 的文件，分别存储输入和输出日志。确保系统中已安装 rsyslog。现在转到 <code>/etc/rsyslog.d</code> 并创建一个名为 <code>nftables.conf</code> 的文件，其内容如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:msg,regex,”Invalid-Input: “ -/var/log/nftables/Input.log</span></span>
<span class="line"><span>:msg,regex,”Invalid-Output: “ -/var/log/nftables/Output.log &amp; stop</span></span></code></pre></div><p>现在，我们必须确保日志是可管理的。为此，使用以下代码在 <code>/etc/logrotate.d</code> 中创建另一个名为 <code>nftables</code> 的文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/var/log/nftables/* { rotate 5 daily maxsize 50M missingok notifempty delaycompress compress postrotate invoke-rc.d rsyslog rotate &gt; /dev/null endscript }</span></span></code></pre></div><p>重新启动 nftables。现在，你可以检查你的规则集。如果你觉得在终端中键入每个命令很麻烦，则可以使用脚本来加载 nftables 防火墙。我希望本文对保护你的系统有用。</p><hr>`,55)),n("p",null,[e[1]||(e[1]=s("via: ",-1)),a(t,{href:"https://opensourceforu.com/2019/10/transition-to-nftables/"},{default:i(()=>[...e[0]||(e[0]=[s("https://opensourceforu.com/2019/10/transition-to-nftables/",-1)])]),_:1})]),n("p",null,[e[6]||(e[6]=s("作者：",-1)),a(t,{href:"https://opensourceforu.com/author/vijay-marcel/"},{default:i(()=>[...e[2]||(e[2]=[s("Vijay Marcel D",-1)])]),_:1}),e[7]||(e[7]=s(" 选题：",-1)),a(t,{href:"https://github.com/lujun9972"},{default:i(()=>[...e[3]||(e[3]=[s("lujun9972",-1)])]),_:1}),e[8]||(e[8]=s(" 译者：",-1)),a(t,{href:"https://github.com/wxy"},{default:i(()=>[...e[4]||(e[4]=[s("wxy",-1)])]),_:1}),e[9]||(e[9]=s(" 校对：",-1)),a(t,{href:"https://github.com/wxy"},{default:i(()=>[...e[5]||(e[5]=[s("wxy",-1)])]),_:1})]),n("p",null,[e[12]||(e[12]=s("本文由 ",-1)),a(t,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[10]||(e[10]=[s("LCTT",-1)])]),_:1}),e[13]||(e[13]=s(" 原创编译，",-1)),a(t,{href:"https://linux.cn/"},{default:i(()=>[...e[11]||(e[11]=[s("Linux中国",-1)])]),_:1}),e[14]||(e[14]=s(" 荣誉推出",-1))])])}const C=l(c,[["render",f]]);export{v as __pageData,C as default};
